import {
  type OnChangeFn,
  type RowData,
  type Updater,
  functionalUpdate,
} from '@tanstack/react-table';
import React from 'react';
import { FormattedMessage } from 'react-intl';

import { WrapTextIcon } from '@dynatrace/strato-icons';

import {
  DataTableV2ActionsMenu,
  _useDataTableV2UserActionContext,
} from './UserActions.js';
import { _useControllableState } from '../../../core/hooks/useControllableState.js';
import { dataTableMessages } from '../../DataTable/messages.js';
import {
  type Column,
  type Table,
  type TableFeature,
  type TableOptions,
} from '../hooks/useTable/types.js';
import { type DataTableV2Props } from '../public.api.js';

/** @public */
export interface DataTableV2LineWrapControlled {
  /**
   * Lets you control the lineWrap state of the entire table or individual columns.
   * `boolean` values will affect the whole table, whereas `Record` values will let you assign
   * lineWraps to individual columns.
   * @example
   * ```typescript
   * lineWrap={true} // for forcing lineWrap on all columns in the table
   * lineWrap={{ [column.id]: true|false }} // to control the lineWrap on individual columns.
   * ```
   */
  lineWrap?: never;

  /**
   * Lets you set lineWrap state initially of the entire table or individual columns.
   * `boolean` values will affect the whole table, whereas `Record` values will let you assign
   * lineWraps to individual columns.
   * @example
   * ```typescript
   * defaultLineWrap={true} // for forcing lineWrap on all columns in the table
   * defaultLineWrap={{ [column.id]: true|false }} // to control the lineWrap on individual columns.
   * ```
   */
  defaultLineWrap?: DataTableV2LineWrapState;
}

/** @public */
export interface DataTableV2LineWrapUncontrolled {
  /**
   * Lets you control the lineWrap state of the entire table or individual columns.
   * `boolean` values will affect the whole table, whereas `Record` values will let you assign
   * lineWraps to individual columns.
   * @example
   * ```typescript
   * lineWrap={true} // for forcing lineWrap on all columns in the table
   * lineWrap={{ [column.id]: true|false }} // to control the lineWrap on individual columns.
   * ```
   */
  lineWrap?: DataTableV2LineWrapState;

  /**
   * Lets you set lineWrap state initially of the entire table or individual columns.
   * `boolean` values will affect the whole table, whereas `Record` values will let you assign
   * lineWraps to individual columns.
   * @example
   * ```typescript
   * defaultLineWrap={true} // for forcing lineWrap on all columns in the table
   * defaultLineWrap={{ [column.id]: true|false }} // to control the lineWrap on individual columns.
   * ```
   */
  defaultLineWrap?: never;
}

/**
 * Interface defining the props on the DataTableV2 that control the line wrapping feature.
 * @public
 */
export type DataTableV2LineWrapProps = (
  | DataTableV2LineWrapControlled
  | DataTableV2LineWrapUncontrolled
) & {
  /**
   * Callback that is called when the lineWrap state of the table or any column is changed.
   */
  onLineWrapChange?: (lineWrap: DataTableV2LineWrapState) => void;
};

/**
 * @public
 * Defines the shape of the LineWrap state within the tanstack tables state.
 */
export type DataTableV2LineWrapState = Record<string, boolean> | boolean;

// Extension interface to extend the tanstack table state with the LineWrap state.
export interface DataTableV2LineWrapTableState {
  /**
   * Table state extension for lineWrap
   */
  columnLineWrap: DataTableV2LineWrapState;
}

// Extension interface to extend the useTable hook options with the LineWrap options.
export interface DataTableV2LineWrapOptions {
  /**
   * Enables line wrapping as a feature on the table.
   */
  enableLineWrap?: boolean;

  /**
   * Exposes the onLineWrapChange function to the Table options.
   */
  onColumnLineWrapChange?: OnChangeFn<DataTableV2LineWrapState>;
}

// Extension interface to extend the types of the tanstack table instance.
export interface DataTableV2LineWrapInstance {
  /**
   * Helper function to update the global table states `columnLineWrap` portion.
   */
  setColumnLineWrap: (updater: Updater<DataTableV2LineWrapState>) => void;
}

// Extension interface to extend the types exposed on the tanstack column instance.
export interface DataTableV2LineWrapColumn {
  /**
   * Returns a boolean value that will represent if the column allows line wrapping.
   */
  getCanLineWrap: () => boolean;

  /**
   * Return a boolean value that will represent the current line wrap state of a column.
   */
  getIsLineWrapped: () => boolean;

  /**
   * Toggles the line wrap property of the column
   * @param value - If a value is provided, this function behaves like a setter instead of a toggle.
   */
  toggleLineWrap: (value?: boolean) => void;
}

// Feature implementation for LineWrap. This contains the logic that will be given
// to the tanstack table. The implementing interface is important as these are
// the function that will be called by the tanstack table core during render.
export const LineWrap: TableFeature = {
  createColumn<TData extends RowData, TValue>(
    column: Column<TData, TValue>,
    table: Table<TData>,
  ) {
    // Add a toggleLineWrap function onto the column so that it can be accessed
    // during rendering.
    column.toggleLineWrap = (value) => {
      if (column.getCanLineWrap()) {
        table.setColumnLineWrap((old) => {
          // Check if the lineWrap was set as a global first
          if (typeof old === 'boolean') {
            return {
              [column.id]: value ?? !column.getIsLineWrapped(),
            };
          }
          return {
            ...old,
            [column.id]: value ?? !column.getIsLineWrapped(),
          };
        });
      }
    };

    // Helper function that will allow access to the lineWrap state of an
    // individual column.
    column.getIsLineWrapped = () => {
      const lineWrapState = table.getState().columnLineWrap;
      // Boolean values define a global line wrapping on the table.
      if (typeof lineWrapState === 'boolean') {
        return lineWrapState;
      }

      return lineWrapState?.[column.id] ?? false;
    };

    // Helper function that lets a column check during render if can be line-wrapped.
    column.getCanLineWrap = () => {
      return table.options.enableLineWrap ?? true;
    };
  },

  createTable<TData extends RowData>(table: Table<TData>): void {
    table.setColumnLineWrap = (updater) => {
      const newValue = functionalUpdate(
        updater,
        table.getState().columnLineWrap ?? false,
      );
      table.options.onColumnLineWrapChange?.(newValue);
    };
  },
};

/**
 * Configuration hook for the DataTableV2 LineWrap feature.
 */
export function useColumnLineWrap<T>(
  props: DataTableV2Props<T>,
  options: TableOptions<T>,
) {
  const [columnLineWrap, onColumnLineWrapChange] = _useControllableState({
    value: props.lineWrap,
    defaultValue: props.defaultLineWrap,
    onChange: props.onLineWrapChange,
  });

  options.state = { ...options.state, columnLineWrap };
  options.onColumnLineWrapChange = onColumnLineWrapChange;
}

//# region Providing actions

/**
 *
 * Out of the box line wrap toggle for header and cell actions.
 * @internal
 */
export function _LineWrapAction() {
  const { column } = _useDataTableV2UserActionContext();

  return (
    <DataTableV2ActionsMenu.Item onSelect={() => column.toggleLineWrap()}>
      <DataTableV2ActionsMenu.ItemIcon>
        <WrapTextIcon />
      </DataTableV2ActionsMenu.ItemIcon>
      {column.getIsLineWrapped() ? (
        <FormattedMessage {...dataTableMessages.disableLineWrapLabel} />
      ) : (
        <FormattedMessage {...dataTableMessages.enableLineWrapLabel} />
      )}
    </DataTableV2ActionsMenu.Item>
  );
}

//# endregion Providing actions
